package me.zenith.skypvp.manager;
import me.zenith.skypvp.ZenithSkyPvP; import org.bukkit.*; import org.bukkit.configuration.file.YamlConfiguration; import org.bukkit.entity.Player; import java.io.*;
public class SpawnManager {private final ZenithSkyPvP p; private final File f; private YamlConfiguration y; public SpawnManager(ZenithSkyPvP p){this.p=p;f=new File(p.getDataFolder(),"locations.yml");y=YamlConfiguration.loadConfiguration(f);} public boolean has(){return y.getBoolean("spawn-set",false);} public Location get(){if(!has())return null; World w=Bukkit.getWorld(y.getString("world")); if(w==null)return null; return new Location(w,y.getDouble("x"),y.getDouble("y"),y.getDouble("z"),(float)y.getDouble("yaw"),(float)y.getDouble("pitch"));} public void set(Player pl){Location l=pl.getLocation();y.set("spawn-set",true);y.set("world",l.getWorld().getName());y.set("x",l.getX());y.set("y",l.getY());y.set("z",l.getZ());y.set("yaw",(double)l.getYaw());y.set("pitch",(double)l.getPitch());try{y.save(f);}catch(IOException e){p.getLogger().warning(e.getMessage());}}}
